// TextInput (ds-metrics §16 — LabeledInputField + OTP error border): label (bodyStrong, el9) → 52pt field box (padding
// h 16, radius card, bg1Elevated, 1pt border el3 ≈ controlBorder, error → error) → hint / error text (caption), gaps 8 / 2.
// The textField itself is the child (slot): template events carry no payload, so a textField inside the template could
// not hand its text to the screen — the screen binds its own field:
//   {"type": "TextInput", "id": "email", "props": {"label": "E-mail", "error": "=emailError"}, "children": [
//     {"type": "textField", "id": "emailField", "props": {"bind": "email", "placeholder": "you@mail.com", "width": "fill"}}]}
param label: string = ""
param hint: string = ""
param error: string = ""
